package connect

// ResultOf computes the winner of a game of Hex given a board where each
// string is a row of the board. The board is a slanted parallelogram of
// hexagonal cells: after the spaces are stripped, every row has the same
// width and each row is shifted one cell to the right relative to the one
// above it.
//
// Player "X" connects the left side to the right side, and player "O"
// connects the top side to the bottom side. The returned string is "X",
// "O", or "" when neither player has a winning connection.
func ResultOf(lines []string) (string, error) {
	h := len(lines)
	if h == 0 {
		return "", nil
	}
	w := len(lines[0])

	// X wins by connecting the left edge (column 0) to the right edge
	// (column w-1).
	if connects(lines, h, w, 'X',
		func(r, c int) bool { return c == 0 },
		func(r, c int) bool { return c == w-1 }) {
		return "X", nil
	}

	// O wins by connecting the top edge (row 0) to the bottom edge
	// (row h-1).
	if connects(lines, h, w, 'O',
		func(r, c int) bool { return r == 0 },
		func(r, c int) bool { return r == h-1 }) {
		return "O", nil
	}

	return "", nil
}

// connects reports whether the player's stones contain a connected path from
// any cell matching start to any cell matching goal.
func connects(lines []string, h, w int, player byte, start, goal func(r, c int) bool) bool {
	visited := make([][]bool, h)
	for i := range visited {
		visited[i] = make([]bool, w)
	}

	// Seed the flood fill with every stone on the start edge.
	var queue [][2]int
	for r := 0; r < h; r++ {
		for c := 0; c < w; c++ {
			if lines[r][c] == player && start(r, c) {
				visited[r][c] = true
				queue = append(queue, [2]int{r, c})
			}
		}
	}

	for len(queue) > 0 {
		cell := queue[0]
		queue = queue[1:]
		r, c := cell[0], cell[1]

		if goal(r, c) {
			return true
		}

		for _, n := range hexNeighbors(r, c) {
			nr, nc := n[0], n[1]
			if nr < 0 || nr >= h || nc < 0 || nc >= w {
				continue
			}
			if visited[nr][nc] || lines[nr][nc] != player {
				continue
			}
			visited[nr][nc] = true
			queue = append(queue, [2]int{nr, nc})
		}
	}

	return false
}

// hexNeighbors returns the six hexagonal neighbors of the cell at (row, col).
// Because each row is shifted one cell right relative to the row above, the
// diagonal neighbors are (row-1, col), (row-1, col+1) above and
// (row+1, col-1), (row+1, col) below.
func hexNeighbors(row, col int) [6][2]int {
	return [6][2]int{
		{row, col - 1},
		{row, col + 1},
		{row - 1, col},
		{row - 1, col + 1},
		{row + 1, col - 1},
		{row + 1, col},
	}
}
